    for char in reversed(s):
        value = roman[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def parse_price(s: str) -> float:
    s = s.replace('$', '').replace(',', '')
    return float(s)

def median(nums: list) -> float:
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    mid = n // 2
    if n % 2 == 0:
        return (nums_sorted[mid - 1] + nums_sorted[mid]) / 2
    else:
        return float(nums_sorted[mid])

def shipping_cost(kg: float) -> float:
    if kg <= 1:
        return 5.0
    return 5.0 + 2.0 * int(kg)

def c_to_f(c: float) -> float:
    f = c * 9 / 5 + 32
    return round(f, 1)

def state_tax(state: str, amount: float) -> float:
    import json
    with open('config/tax_rates_2025.json') as f:
        rates = json.load(f)
    rate = rates.get(state.upper(), 0.0)
    return round(amount * rate, 2)

def flatten(xs: list) -> list:
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def second_largest(nums: list) -> int:
    unique_nums = list(set(nums))
    if len(unique_nums) < 2:
        raise ValueError("Not enough distinct elements")
    unique_nums.sort()
    return unique_nums[-2]

def merge_intervals(iv: list) -> list:
    if not iv:
        return []
    iv.sort()
    merged = [iv[0]]
    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1] + 1:
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)
    return merged
